from pathlib import Path
import re

out=Path(__file__).parent
css='''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#10151c;color:#e6edf3;font:14px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}a{color:#a6c5ff}a:focus-visible,summary:focus-visible{outline:2px solid #80adff;outline-offset:4px}main{max-width:1060px;margin:auto;padding:58px 26px 72px}.eyebrow{color:#91a5bd;font-size:12px;letter-spacing:.08em;text-transform:uppercase}.intro h1{font-weight:500;font-size:38px;letter-spacing:-1.8px;margin:12px 0}.intro p{color:#b3c1d0;max-width:73ch}.options{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:30px 0 50px}.options a{display:block;text-decoration:none;border:1px solid #35465a;padding:17px 18px;color:#cbd5e1;background:#17202b}.options strong{display:block;font-size:14px;color:#edf4fd;margin:0 0 5px}.options small{color:#9caec2;line-height:1.5}.options a:first-child{border-color:#7aa2f7}.direction{margin:60px 0 80px;scroll-margin-top:24px}.direction-head{display:flex;justify-content:space-between;align-items:start;gap:18px;margin-bottom:22px}.direction-head h2{font-size:23px;font-weight:500;margin:0 0 7px}.direction-head p{font-size:13px;color:#aabacf;margin:0;max-width:72ch}.recommend{white-space:nowrap;color:#a6c5ff;border:1px solid #4f77b6;padding:4px 10px;font-size:11px;margin-top:5px}.frame{border:1px solid #394b62;border-radius:7px;overflow:hidden;box-shadow:0 14px 40px #0003}.filebar{padding:12px 25px;font-size:12px;background:#202b3a;color:#c3cfdf;border-bottom:1px solid #394b62;display:flex;justify-content:space-between}.readme{background:#fff;color:#1f2328;font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;padding:38px 42px;--bgColor-muted:#f6f8fa;overflow-wrap:break-word}.readme h1{font-size:32px;font-weight:600;border-bottom:1px solid #d1d9e0b3;padding-bottom:.3em;margin:0 0 16px;line-height:1.25}.readme h2{font-size:24px;font-weight:600;border-bottom:1px solid #d1d9e0b3;padding-bottom:.3em;margin:28px 0 16px;line-height:1.25}.readme h3{font-size:20px;line-height:1.25;margin:24px 0 16px}.readme a{color:#0969da;text-decoration:none}.readme a:hover{text-decoration:underline}.readme p{margin:0 0 16px}.readme ul{margin:0 0 16px;padding-left:2em}.readme li+li{margin-top:5px}.readme strong{font-weight:600}.readme em{font-size:14px;color:#59636e}.readme img{max-width:100%;height:auto;vertical-align:middle}.readme pre{padding:16px;overflow:auto;font-size:85%;line-height:1.45;background:#f6f8fa;border-radius:6px;margin:0 0 16px}.readme code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:85%;padding:.2em .4em;background:#818b981f;border-radius:6px}.readme pre code{padding:0;background:none;font-size:100%}.readme table{border-collapse:collapse;max-width:100%;width:100%;margin:0 0 16px;overflow:auto}.readme td,.readme th{padding:8px 13px;border:1px solid #d1d9e0}.readme th{text-align:left;font-weight:600}.readme tr:nth-child(2n){background:#f6f8fa}.readme td:has(img){width:50%;padding:8px}.readme details{margin:0 0 16px}.readme summary{cursor:pointer;margin-bottom:10px}.readme [align=center]{text-align:center}.readme [align=center]>a:first-child{display:inline-block;margin-bottom:13px}.readme [align=center] h1{border:0;padding:0;margin-bottom:10px}.readme [align=center] p:first-of-type{font-size:20px}.after{color:#9eafc3;font-size:12px;margin-top:16px}.end{border-top:1px solid #334358;padding-top:28px;color:#aabacf}.end a{margin-right:20px}@media(max-width:720px){main{padding:30px 14px}.intro h1{font-size:30px}.options{grid-template-columns:1fr;gap:9px}.direction-head{display:block}.recommend{display:inline-block;margin-top:12px}.readme{padding:24px 18px;font-size:15px}.readme h1{font-size:28px}.readme h2{font-size:22px}.filebar{padding:10px 16px}.filebar span:last-child{display:none}.readme table{font-size:13px}}
'''
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blockyard · README directions</title><style>'''+css+'''</style></head><body><main><header class="intro"><div class="eyebrow">Blockyard / README preview</div><h1>Show the app first.</h1><p>Three ways to introduce Blockyard on GitHub. Each starts with the product, shows the actual interface with demo data, and moves build instructions into supporting docs.</p><p>I recommend A: a full-size map, clear features, theme support and a short install section.</p></header><nav class="options"><a href="#a"><strong>A / Screenshot first</strong><small>A familiar open-source README. Recommended.</small></a><a href="#b"><strong>B / Walkthrough</strong><small>See the map, explore details, review cleanup.</small></a><a href="#c"><strong>C / Omarchy first</strong><small>Lead with themes and keyboard navigation.</small></a></nav>'''
for letter,title,desc,note in [
 ('A','Screenshot first','One clear introduction, a large map, useful features and installation. The cleanup screenshot sits in an expandable section.','Best balance for a visitor deciding whether to download. Screenshots can be opened at full size.'),
 ('B','Walkthrough','Three screenshots explain the main workflow in order. Longer, but gives a new user a guided first look.','Best for explaining the interaction. Takes more scrolling to reach the full installation section.'),
 ('C','Omarchy first','Dark and light views lead together, followed by the folder list and keyboard controls.','Best for Omarchy users who care most about fitting their desktop. The two-up images trade legibility for a quick theme comparison.')]:
    body=(Path('.tools/readme-capture')/f'{letter}.html').read_text()
    body=body.replace(' target="_blank"', '')
    prefix=letter.lower()
    body=re.sub(r'<h([1-6]) dir="auto">([^<]+)</h\1>',lambda m: f'<h{m[1]} id="{prefix}-'+re.sub(r'[^a-z0-9 -]','',m[2].lower()).replace(' ','-')+f'">{m[2]}</h{m[1]}>',body)
    body=body.replace('href="#install"',f'href="#{prefix}-install"')
    html+=f'<section class="direction" id="{prefix}"><header class="direction-head"><div><h2>{letter} / {title}</h2><p>{desc}</p></div>'+('<span class="recommend">Recommended</span>' if letter=='A' else '')+f'</header><div class="frame"><div class="filebar"><span>allisonmahmood / blockyard / README.md</span><span>Proposed GitHub rendering</span></div><article class="readme">{body}</article></div><p class="after">{note}</p><a href="#top">Back to comparison</a></section>'
html+='''<footer class="end"><p>The app screenshots are unretouched captures of the existing Qt interface. All folder names, sizes, counts and disk capacity are illustrative. The published README will use normal GitHub Markdown and images, not this comparison page's outer styling.</p><p>Developer build, uninstall and full keyboard instructions will move to linked documentation when the selected direction is implemented.</p><nav><a href="#a">A / Screenshot first</a><a href="#b">B / Walkthrough</a><a href="#c">C / Omarchy first</a></nav></footer></main></body></html>'''
html=html.replace('<header class="intro">','<header class="intro" id="top">')
(out/'options.html').write_text(html)
print('Wrote README comparison:',len(html.encode()),'bytes')
